                              "            control_status = row.get(\"control_status\")\n            finding_status = row.get(\"finding_status\")\n            if control_status not in {\"PASS\", \"INSUFFICIENT_DATA\", \"ERROR\"} or finding_status not in {\"FINDING\", \"NO_FINDING\", \"UNKNOWN\"}:\n                raise ValueError(\"principal status is malformed\")\n            if control_status == \"PASS\" and finding_status not in {\"FINDING\", \"NO_FINDING\"}:\n                raise ValueError(\"PASS principal has no evaluated finding state\")\n            if control_status != \"PASS\" and finding_status != \"UNKNOWN\":\n                raise ValueError(\"non-PASS principal claims an evaluated finding state\")\n            observed_events = integer(row, \"observed_events\")\n            row_error_count += int(control_status == \"ERROR\")\n            row_insufficient_count += int(control_status == \"INSUFFICIENT_DATA\")\n            row_finding_count += int(finding_status == \"FINDING\")\n            row_observed_count += int(observed_events &gt; 0)\n            coverage_partial = coverage_partial or observed_events &lt; 1"
